"""English-only, progressively enhanced pages. The prose is not generated at runtime."""
from html import escape as e
import re
REPO='https://github.com/spicmaff/malonaldehyde-transition-sampling'
SECTIONS=['overview','molecule','sampling','landscape','seeds','applicability','train119','story','longread','reproduce']

def molecule_svg(xyz):
    p=[(62+(x-6.35)*109,366-(y-6.3)*83) for x,y,z in xyz]
    bonds=[(0,2),(2,3),(2,4),(4,5),(4,6),(6,7),(6,8)]
    s='<svg viewBox="0 0 560 390" role="img" aria-label="Malonaldehyde: nine atoms on the saved PBE path"><title>Malonaldehyde, saved central NEB geometry</title>'
    for i,j in bonds+[(0,1),(1,7)]:
        dash=' stroke-dasharray="5 6"' if 1 in (i,j) else ''
        s+=f'<line x1="{p[i][0]}" y1="{p[i][1]}" x2="{p[j][0]}" y2="{p[j][1]}" stroke="currentColor" opacity=".45" stroke-width="3"{dash}/>'
    for i,(x,y) in enumerate(p):
        color='var(--oxygen)' if i in (0,7) else 'var(--targeted)' if i==1 else 'var(--carbon)' if i in (2,4,6) else 'var(--hydrogen)'
        r=18 if i in (0,7) else 13 if i==1 else 16 if i in (2,4,6) else 10
        s+=f'<circle cx="{x}" cy="{y}" r="{r}" fill="{color}" stroke="var(--panel)" stroke-width="2"/>'
        if i in (0,1,7):s+=f'<text x="{x}" y="{y+36}" text-anchor="middle" fill="var(--ink)" font-size="15">'+('H*' if i==1 else 'O')+'</text>'
    return s+'</svg>'

def render(d,article):
    names=(['Overview','Molecule','Sampling','Energy landscape','Five seeds','Applicability','Train119','Films','Longread','Reproduce'])
    def source(*keys):
        links=''.join(f'<li><a href="{d["evidence"][k]["url"]}">{e(d["evidence"][k]["path"])}</a><small>SHA-256 {d["evidence"][k]["sha256"]}</small></li>' for k in keys)
        return f'<details class="source"><summary>{("Evidence & source files")}</summary><ul>{links}</ul></details>'
    def head(n,eyebrow,title,lead):return f'<div class="page-head"><p class="eyebrow"><span>{n:02d}</span> / {eyebrow}</p><h1 id="title-{SECTIONS[n]}">{title}</h1><p class="lede">{lead}</p></div>'
    def sec(id,body):return f'<section class="page" id="{id}" aria-labelledby="title-{id}">{body}</section>'
    def note(s):return f'<aside class="note">{s}</aside>'
    def table(headers,rows,caption):return '<div class="table-wrap"><table><caption>'+caption+'</caption><thead><tr>'+''.join(f'<th scope="col">{x}</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join(f'<td>{x}</td>' for x in r)+'</tr>' for r in rows)+'</tbody></table></div>'
    def fallback(headers,rows,caption):return '<details class="values"><summary>'+('Read the numerical table')+'</summary>'+table(headers,rows,caption)+'</details>'
    def pill(s,cl=''):return f'<span class="badge {cl}">{s}</span>'
    def nextlink(id,title):return f'<a class="next-link" href="#{id}">{title}<span aria-hidden="true">↗</span></a>'
    def chart(id):return f'<div class="chart" id="{id}"><p class="js-only loading">{("Loading the verified data…")}</p></div>'
    main=[]
    # 00 — overview
    overview=f'''<div class="hero"><div class="hero-copy"><p class="eyebrow">DFT · MTP · {('A research story')}</p><h1 id="title-overview">{('One proton.<br>Two ways<br>to <em>learn.</em>')}</h1><p class="lede">{('A small molecule asks a difficult question: where should a machine potential learn—and when should we trust it?')}</p><p class="byline">{('Mikhail Fofonov')} <span>·</span> {('Malonaldehyde / computational chemistry')}</p><div class="actions"><a class="button primary" href="#molecule">{('Explore the molecule')} <span>↗</span></a><a class="text-link" href="#longread">{('Read the story')} →</a></div></div><figure class="hero-visual"><div class="figure-meta"><span>C₃H₄O₂</span><span>{('Saved PBE path')}</span></div><div id="hero-molecule">{molecule_svg(d['molecule'][4]['xyz'])}</div><div class="hero-coordinate"><span>O—H* ··· O</span><strong id="hero-q">q<sub>PT</sub> ≈ 0 Å</strong></div><label class="js-only slider-label" for="hero-scrub">{('Move the proton along the path')}<input id="hero-scrub" type="range" min="0" max="8" step="1" value="4"></label><figcaption>{('Nine computed geometries, not a movie of a reaction. Explore the saved images; animation is display interpolation, never physical time.')}</figcaption></figure></div>
    <div class="research-spine"><div class="section-bar"><h2>{('The story, in four observations')}</h2><span class="small">{('Results and limits belong together.')}</span></div><div class="spine-grid">'''
    cards=[('36 + 24',('Same budget. Different places.'),('Both original models learn from 60 DFT configurations. Placement, not a larger budget, changes.'),'sampling',('Locked comparison')),
           (('35.25 → 4.10'),('A much smaller barrier error.'),('meV, for the original saved model pair—not a promise for every training run.'),'landscape',('Original pair')),
           ('3 / 5',('Randomness changes the story.'),('Paired seeds where targeted wins both metrics. The ordering is seed-sensitive.'),'seeds','SEED_SENSITIVE'),
           ('11 / 11',('Local accuracy, not deployment.'),('Later Train119 checks satisfy A2 locally. Its frozen applicability failure still stands.'),'train119',('Development diagnostic'))]
    for number,title,desc,route,badge in cards:overview+=f'<article class="spine-item">{pill(badge)}<div class="number">{number}</div><h3>{title}</h3><p>{desc}</p><a href="#{route}">{("Explore")} →</a></article>'
    overview+='</div></div>'+source('methods','path','seeds','diagnostic')+note(('<strong>Accuracy is not reliability.</strong> PBE agreement, training stability, data independence and applicability are different questions. This exhibit keeps them separate.'))
    main.append(sec('overview',overview))
    # 01 — molecule
    body=head(1,('Geometry before metrics'),('A proton between two oxygens.'),('Follow the nine saved PBE NEB images from one minimum to the other. The molecular scaffold changes as the proton moves.'))
    body+=f'''<div class="split molecule-layout"><figure class="panel molecule-panel"><div class="figure-meta"><span>{('Exact image / display interpolation')}</span><span id="mol-image-label">5 / 9</span></div><div id="molecule-view">{molecule_svg(d['molecule'][4]['xyz'])}</div><div class="controls js-only"><button id="mol-prev" aria-label="{('Previous image')}">←</button><button id="mol-play" class="primary">{('Play path')}</button><button id="mol-next" aria-label="{('Next image')}">→</button><button id="mol-reset">{('Reset')}</button></div><div class="js-only"><label class="slider-label" for="mol-frame">{('Saved image')}<input id="mol-frame" type="range" min="0" max="8" step="1" value="4"></label><label class="slider-label" for="mol-angle">{('Viewing angle — display only')}<input id="mol-angle" type="range" min="-50" max="50" value="0"></label></div><figcaption id="motion-note">{('No physical clock. No new energies are calculated between images.')}</figcaption></figure><div><div class="panel"><h2>{('One coordinate, two minima')}</h2><p class="equation">q<sub>PT</sub> = r(O₁–H*) − r(O₂–H*)</p><p>{('Negative: the proton is closer to O₁. Positive: closer to O₂. Near zero: similar O–H distances. O₁ and O₂ are fixed atom labels, not positions that change with the viewing angle.')}</p><div id="mol-metrics" class="metric-grid"></div></div><div class="panel chart-panel"><h3>{('PBE energy along the saved path')}</h3>{chart('mol-energy')}<p class="small">{('Energy relative to the lower endpoint. Lines are visual guides between computed points.')}</p></div></div></div>'''
    body+=fallback([('Image'),'qPT / Å','r(O₁–H*) / Å','r(O₂–H*) / Å','PBE / meV'],[[m['image'],f'{m["q"]:.6f}',f'{m["left"]:.6f}',f'{m["right"]:.6f}',f'{d["profiles"]["PBE"][i]:.6f}'] for i,m in enumerate(d['molecule'])],('All nine saved geometries'))+source('path')+nextlink('sampling',('Where should the model learn?'))
    main.append(sec('molecule',body))
    # 02 — sampling
    body=head(2,('Equal data budget'),('Same sixty. Different coverage.'),('Keep the architecture and training settings fixed. Keep 36 shared configurations. Move the other 24 from the minima toward the transition region.'))
    body+=f'<div class="budget-row"><div><span>{("Shared foundation")}</span><strong>36</strong></div><b>+</b><div><span>{("Strategy-specific")}</span><strong>24</strong></div><b>=</b><div><span>{("Per MTP model")}</span><strong>60</strong></div></div>'
    body+=f'<div class="panel"><div class="section-bar"><div><h2>{("Where the training geometries lie")}</h2><p class="small">{("A projection of real training configurations: qPT against O–O distance. Not a free-energy surface.")}</p></div><label class="js-only">{("Show")}<select id="sampling-branch"><option value="both">{("Both strategies")}</option><option value="basin">Basin60</option><option value="targeted">Targeted60</option></select></label></div>{chart("sampling-chart")}<div class="legend"><span class="shared">◆ {("Shared 36")}</span><span class="basin">● Basin +24</span><span class="targeted">● Targeted +24</span></div></div>'
    body+=note(('<strong>K = pool size = 24.</strong> Every transition candidate was selected. The experiment tests spatial allocation, not the ability of MaxVol to rank a smaller subset from a larger candidate pool.'))+source('train_basin','train_targeted','methods')+nextlink('landscape',('What changed in the energy profile?'))
    main.append(sec('sampling',body))
    # 03 — energy
    body=head(3,('The original locked pair'),('Learning the barrier. Missing the shape.'),('Compare PBE with the two original 60-configuration MTPs on the same saved path. A small average error near a minimum is not a guarantee at the transition.'))
    body+=f'<div class="panel"><div class="section-bar"><h2>{("Nine images, three profiles")}</h2><div class="controls js-only">'+''.join(f'<label class="check"><input type="checkbox" data-series="{k}" checked><span class="{k.lower()}">{k}</span></label>' for k in ['PBE','Basin60','Targeted60'])+'</div></div>'+chart('landscape-chart')+f'<label class="slider-label js-only" for="landscape-frame">{("Inspect image")}<input id="landscape-frame" type="range" min="0" max="8" value="4"></label><div id="landscape-readout" class="readout" aria-live="polite"></div></div>'
    body+=table([('Model'),('Barrier / meV'),('Barrier error / meV'),('Central force RMSE / eV Å⁻¹')],[[k,f'{d["metrics"][k]["barrier"]:.6f}',f'{d["metrics"][k]["barrier_error"]:.6f}',f'{d["metrics"][k]["force_rmse"]:.6f}'] for k in ['PBE','Basin60','Targeted60']],('Original model pair · smaller errors mean closer agreement with the PBE reference'))
    body+=note(('Each profile is referenced to its <strong>own lower endpoint</strong>. The discrete barrier is max(E) − min(E₁, E₉). Force RMSE uses the three central images, |qPT| ≤ 0.15 Å. Both endpoint geometries overlap training; the whole path is not an independent holdout.'))+source('path','basin','targeted','methods')+nextlink('seeds',('Does the advantage survive another initialization?'))
    main.append(sec('landscape',body))
    # 04 — seeds
    body=head(4,('A robustness check'),('Five seeds. A less simple answer.'),('All five paired trainings are shown, not just the best result. Switch the metric, then inspect one pair without hiding the others.'))
    body+=f'<div class="split"><div class="panel"><div class="control-row js-only"><label>{("Error metric")}<select id="seed-metric"><option value="barrier">{("Barrier error / meV")}</option><option value="force">{("Transition force RMSE / eV Å⁻¹")}</option></select></label><label>{("Inspect pair")}<select id="seed-select"><option value="all">{("All five")}</option>'+''.join(f'<option value="{i}">{i+1}</option>' for i in range(5))+'</select></label></div>'+chart('seed-chart')+f'<div class="legend"><span class="basin">● Basin60</span><span class="targeted">● Targeted60</span></div><p id="seed-readout" class="small" aria-live="polite"></p></div><aside class="panel editorial-panel"><p class="eyebrow">SEED_SENSITIVE</p><div class="stat-large">3 <em>/ 5</em></div><h2>'+('Targeted wins both metrics.')+'</h2><p>'+('Four of five on the barrier. Three of five on transition forces. One pair reverses both metrics; another splits the outcome.')+'</p><p>'+('These five pairs demonstrate sensitivity, not a reliable estimate of the chance of winning a future training run.')+'</p></aside></div>'
    body+=fallback([('Pair'),('Model'),'seed (uint64)',('Barrier error / meV'),'RMSE / eV Å⁻¹'],[[r['index']+1,r['model'],r['seed'],f'{r["barrier"]:.6f}',f'{r["force"]:.6f}'] for r in d['seeds']],('Exact seeds are stored as strings to preserve 64-bit identity'))+note(('The original run interleaved evaluation and training. A later evaluation-only repair reproduced all ten prediction files byte-for-byte. The historical nonconformance remains recorded; no best seed was selected.'))+source('seeds','randomness','science')+nextlink('applicability',('Now ask a different question: can it move?'))
    main.append(sec('seeds',body))
    # 05 — applicability
    body=head(5,('Two different diagnostics'),('A warning is not an error bar.'),('MaxVol gamma describes a query relative to an active basis. A PBE force error compares two force arrays. They are not interchangeable measurements.'))
    body+=f'<div class="concept-pair"><article><span class="eyebrow">01 / γ</span><h2>{("Applicability / coverage")}</h2><p>{("A selector-dependent algebraic diagnostic. It can trigger a frozen stopping rule; it is not a force error in eV/Å.")}</p></article><article><span class="eyebrow">02 / ΔF</span><h2>{("PBE-reference accuracy")}</h2><p>{("A local measured discrepancy between MTP and saved PBE forces on the same geometry. It does not certify every later trajectory.")}</p></article></div>'
    body+=f'<div class="panel"><div class="section-bar"><div><h2>Replay228 · Train119</h2><p class="small">{("Saved scores of the frozen force-aware selector; no new grading.")}</p></div><label class="js-only">{("Window")}<select id="gamma-window"><option value="all">{("All 228")}</option><option value="crossing">Crossing7 · 142–148</option><option value="challenge">Challenge4 · 93–96</option></select></label></div>{chart("gamma-chart")}<p class="small">{("Frame index is an archive index, not a continuous physical time axis. Zoom changes the display, never the stopping threshold.")}</p></div>'
    body+=f'<div class="timeline"><div><span>Targeted60</span><p>{("Six first attempted updates at 100, 300 and 500 K were rejected by the historical applicability threshold. No usable free MD trajectory resulted.")}</p></div><div><span>Tube92 → Train119</span><p>{("Later adaptive work examined selector equations and local PBE errors. Those diagnoses do not retroactively clear the earlier gates.")}</p></div><div><span>Stage91J</span><p>{("Five of 228 frames exceed 1.0000012996964838. The status remains STATIC_APPLICABILITY_FAIL.")}</p></div></div>'+source('replay','science','continuation')+nextlink('train119',('Measure the forces on the rejected neighborhood'))
    main.append(sec('applicability',body))
    # 06 — Train119
    body=head(6,('October 5 diagnostic · published October 9'),('Small local errors.<br>An unchanged failure.'),('Examine eleven saved 100 K development frames. Crossing7 received seven historical PBE single points; Challenge4 reused four existing references. The Train119 model was unchanged.'))
    body+=f'<div class="section-bar"><span class="badge warning">STATIC_APPLICABILITY_FAIL</span><label class="js-only">{("Inspect a frame")}<select id="case-frame">'+''.join(f'<option value="{r["replay_index"]}">{r["role"]} / {r["replay_index"]}</option>' for r in d['local'])+'</select></label></div>'
    body+=f'<div class="split"><figure class="panel"><h2>{("Coverage score γ")}</h2>{chart("case-gamma")}<figcaption>{("Dimensionless. The dashed line is the unchanged numerical stop.")}</figcaption></figure><figure class="panel"><h2>{("Force-component RMSE")}</h2>{chart("case-force")}<figcaption>{("eV/Å. A2 is a bound on per-configuration RMSE, not on every component.")}</figcaption></figure></div><div id="case-readout" class="readout" aria-live="polite"></div>'
    body+=note(('<strong>Two correlated segments, not eleven IID tests.</strong> Challenge4 frames 93–96 precede training additions 97–100. Replay228 was repeatedly used in development. Good local force errors do not justify loosening the historical stop.'))
    body+=fallback([('Frame'),('Subset'),'γ',('Force RMSE / eV Å⁻¹'),('Above stop')],[[r['replay_index'],r['role'],f'{r["gamma_saved"]:.9f}',f'{r["force_component_RMSE_eV_A"]:.9f}',('Yes') if r['above_stop'] else ('No')] for r in d['local']],('All eleven local PBE comparisons'))
    body+=f'<div class="split section-gap"><div class="panel"><h2>{("A separate development path check")}</h2>{chart("case-energy")}<div class="legend"><span class="pbe">● PBE</span><span class="train119">● Train119</span></div></div><div class="panel editorial-panel"><p class="eyebrow">Audit21 · {("Not an independent holdout")}</p><div class="stat-large">{("0.123")} <em>meV</em></div><h2>{("Discrete barrier error")}</h2><p>{("Central-three-image force RMSE: 0.013834 eV/Å. Both NEB endpoints overlap training. A 119-configuration adaptive model is not another branch of the original equal-budget experiment.")}</p><p class="small">{("The full profile is not accurate to 0.123 meV everywhere: its maximum own-endpoint-referenced error is about 0.504 meV.")}</p></div></div>'+source('diagnostic','train119','train119_prediction','geometry','roles','corrections')+nextlink('story',('Watch the original visual chapters'))
    main.append(sec('train119',body))
    # 07 — media
    body=head(7,('The visual archive'),('The experiment, in motion.'),('Five English-title remasters of the October 5 visual release. Only presentation text and decimal punctuation were translated; the original geometries, numbers and scope remain unchanged. The later local Train119 diagnosis is described separately.'))
    films=[('01_proton_path',('One proton, two minima'),'34 s',('Nine saved PBE NEB images. Smooth movement is a display interpolation; screen time is not reaction time.')),
    ('02_equal_budget',('Where to place 24 points?'),'46 s',('The original equal-budget comparison, endpoint overlaps and all five paired seeds—not a best-run selection.')),
    ('03_applicability_boundary',('A boundary we did not erase'),'40 s',('Historical Stage91J closure. The later local PBE diagnostic does not promote the model to reactive dynamics.')),
    ('04_story_teaser',('The story in twenty seconds'),'20 s',('An editorial trailer of the original presentation; not a new physical calculation.')),
    ('05_proton_vertical',('A closer, vertical view'),('Vertical'),('The same saved path, composed for a portrait screen. The interpolation remains illustrative.'))]
    body+='<div class="film-grid">'
    for i,(file,title,time,cap) in enumerate(films):
        body+=f'<figure class="film {"portrait" if i==4 else ""}"><div class="film-head"><span>0{i+1} / {time}</span><h2>{title}</h2></div><video controls playsinline preload="none" poster="assets/{file}_poster.jpg" aria-label="{e(title)}"><source src="media/{file}.mp4" type="video/mp4"></video><figcaption>{cap}</figcaption><div class="film-actions"><a href="media/{file}.mp4" download>{("Download English MP4")} ↗</a><span class="video-state" role="status"></span></div></figure>'
    body+='</div>'+source('media','old_story')+nextlink('longread',('Read the complete research story'))
    main.append(sec('story',body))
    # 08 — longread
    body=head(8,('The complete story'),('Where should twenty-four<br>DFT points go?'),('From a promising energy profile to a more careful account of what a machine potential knows. Updated with the bounded Train119 diagnostic.'))
    body+=f'<div class="article-meta"><span>{("Mikhail Fofonov · research narrative")}</span><a href="longread.en.md" download>{("Download text")} ↓</a><button class="js-only" id="print-story">{("Print / save as PDF")}</button></div><div class="reading-layout"><aside class="reading-aside"><p class="eyebrow">{("Reading map")}</p><div id="reading-toc"></div><p class="small">{("Every chapter is tied to a frozen source. This is a revised editorial narrative, not a new physical experiment.")}</p></aside><article class="prose" id="longread-content">{article}</article></div>'
    body+=source('old_story','methods','randomness','continuation','diagnostic','corrections')+nextlink('reproduce',('Go from the story to the evidence'))
    main.append(sec('longread',body))
    # 09 — reproducibility
    body=head(9,('Open evidence, bounded claims'),('Read it. Inspect it. Reproduce it.'),('The site is a view of frozen public artifacts, not a live potential. Every plotted value can be traced back to a file and a SHA-256 hash.'))
    body+=f'<div class="split"><div class="panel"><h2>{("Three checks, no new physics")}</h2><pre><code>git clone {REPO}.git\ncd malonaldehyde-transition-sampling\npython3 tools/run_public_selftests.py .\npython3 tools/verify_train119_diagnostic.py \\\n  --data data/post_publication/train119_diagnostic_v001\npython3 tools/build_research_site.py --out _site</code></pre><p class="small">{("Python 3.11+; saved-data checks use the standard library. Building this site does not call QE, MLIP or LAMMPS.")}</p><div class="actions"><a class="button primary" href="{REPO}">GitHub ↗</a><a class="button" href="data/science.json" download>JSON ↓</a><a class="button" href="build-manifest.json">SHA-256 ↗</a></div></div><aside class="panel"><p class="eyebrow">{("The boundary of the claim")}</p><h2>{("What this does not show")}</h2><p>{("No validated Train119 reactive MD, no prospective final holdout, no experimental accuracy, no universal gamma-to-error rule. PBE is an internal computational reference.")}</p><p>{("Blind12 remains unrevealed. Historical scientific results, old media and release tags are preserved.")}</p><div class="badges">{pill("SEED_SENSITIVE")}{pill("STATIC_APPLICABILITY_FAIL","warning")}</div></aside></div>'
    body+='<div class="section-gap"><h2>'+('Source index')+'</h2>'
    for k in d['evidence']:body+=source(k)
    body+=f'</div><div class="credits"><h2>{("About this exhibit")}</h2><p>{("Research: Mikhail Fofonov. Editorial and interactive presentation: October 2026. Same-series design reference: Memory / Geometry. Original scientific assets remain authoritative.")}</p><p><a href="{REPO}/blob/main/CITATION.cff">{("Citation metadata")}</a> · <a href="{REPO}/blob/main/docs/RESEARCH_SITE.md">{("Build & licensing notes")}</a> · <a href="https://spicmaff.github.io/rendezvous-grid-mazes/">Memory / Geometry ↗</a></p></div>'
    main.append(sec('reproduce',body))
    nav=''.join(f'<a href="#{id}" data-route="{id}">{name}</a>' for id,name in zip(SECTIONS,names))
    title=('One Proton, Two Ways to Learn — Malonaldehyde')
    description=('An interactive research story about proton transfer, equal-budget MTP sampling, training randomness and the limits of applicability.')
    return f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light dark"><meta name="description" content="{description}"><meta name="theme-color" content="#f5f3ec"><meta property="og:title" content="{title}"><meta property="og:description" content="{description}"><meta property="og:image" content="https://spicmaff.github.io/malonaldehyde-transition-sampling/social-preview.png"><link rel="canonical" href="https://spicmaff.github.io/malonaldehyde-transition-sampling/"><title>{title}</title><link rel="icon" href="favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="style.css"><script type="module" src="app.mjs"></script></head><body><a class="skip" href="#main">{('Skip to content')}</a><header><div class="wrap top"><a class="brand" href="#overview"><svg viewBox="0 0 40 28" aria-hidden="true"><path d="M7 20L13 7H27L33 20"/><path d="M7 20H33" stroke-dasharray="3 4"/><circle cx="7" cy="20" r="4"/><circle cx="33" cy="20" r="4"/><circle cx="20" cy="20" r="3"/></svg><span>PROTON / POTENTIAL</span></a><div class="top-tools"><a class="repository-link" href="{REPO}">GitHub ↗</a><button id="theme" class="theme js-only" aria-label="{('Switch color theme')}">◐ <span>{('Dark')}</span></button></div></div><div class="wrap"><nav aria-label="{('Research sections')}">{nav}</nav></div></header><main id="main" class="wrap" tabindex="-1"><noscript><p class="note">{('The full story and numerical tables below work without JavaScript. Interactive controls require JavaScript; no account or external service is needed.')}</p></noscript><div id="load-error" role="alert" hidden></div>{''.join(main)}</main><footer><div class="wrap footer-inner"><div>PROTON / POTENTIAL <span>·</span> {('Mikhail Fofonov')}</div><div>{('Science snapshot')}: <a href="{REPO}/tree/{d['science_commit']}">{d['science_commit'][:7]}</a> · <a href="#reproduce">{('Evidence & methods')}</a></div></div></footer></body></html>'''
